  </div>;
}

calendar-presets:
import { useState } from 'react';
import { DsDateRangePicker } from '@primasoftllc/design-system';

export function Example() {
  // В продукте эту календарную дату определяет приложение в Europe/Minsk.
  const calendarToday = '2026-10-19';
  function previousCalendarDay(date) {
    let [year, month, day] = date.split('-').map(Number);
    day -= 1;
    if (day === 0) {
      month -= 1;
      if (month === 0) { month = 12; year -= 1; }
      const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
      day = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
    }
    return [String(year).padStart(4, '0'), String(month).padStart(2, '0'), String(day).padStart(2, '0')].join('-');
  }
  const yesterday = previousCalendarDay(calendarToday);
  const [period, setPeriod] = useState({from:calendarToday,to:calendarToday});
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDateRangePicker label="Быстрый период" value={period} onChange={setPeriod}
      timeZone="Europe/Minsk" hint="Опорная дата примера: 19 октября 2026 года."
      presets={[
        {id:'today',label:'Сегодня',value:{from:calendarToday,to:calendarToday}},
        {id:'yesterday',label:'Вчера',value:{from:yesterday,to:yesterday}}
      ]}/>
    <output aria-live="polite">{period.from || '…'} — {period.to || '…'}</output>
  </div>;
}

form-validation:
import { useState } from 'react';
import { DsDateRangePicker, DsButton } from '@primasoftllc/design-system';

export function Example() {
  const [result, setResult] = useState('');
  return <form style={{display:'flex',flexDirection:'column',gap:16}} onSubmit={event => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setResult('Отчёт: ' + data.get('report.from') + ' — ' + data.get('report.to'));
  }} onReset={() => setResult('')}>
    <DsDateRangePicker label="Даты отчёта" name="report" required
      defaultValue={{from:'2026-10-12',to:'2026-10-19'}}
      min="2026-10-01" max="2026-10-31" timeZone="Europe/Minsk"
      hint="Обе даты включительно: с 1 по 31 октября 2026 года."/>
    <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
      <DsButton type="submit">Построить отчёт</DsButton>
      <DsButton type="reset" tone="secondary">Сбросить</DsButton>
    </div>
    <span role="status">{result}</span>
  </form>;
}

