import { DsDateRangePicker } from '@primasoftllc/design-system';

export function Example() {
  const period = {from:'2026-10-12',to:'2026-10-19'};
  const presets = [{id:'week',label:'Неделя',value:period}];
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsDateRangePicker label="Подтверждённый период" defaultValue={period} readOnly
      timeZone="Europe/Minsk" presets={presets} hint="Сначала отмените подтверждение."/>
    <DsDateRangePicker label="Недоступный период" defaultValue={period} disabled
      timeZone="Europe/Minsk" presets={presets} hint="Недостаточно прав для изменения."/>
  </div>;
}
